function insert(intervals, newInterval) {
  const res = [];
  let [newL, newR] = newInterval, i = 0;
  while (i < intervals.length && intervals[i][1] < newL) res.push(intervals[i++]);
  while (i < intervals.length && intervals[i][0] <= newR) {
    newL = Math.min(newL, intervals[i][0]);
    newR = Math.max(newR, intervals[i][1]);
    i++;
  }
  res.push([newL, newR]);
  while (i < intervals.length) res.push(intervals[i++]);
  return res;
}
